class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        byb = [[] for _ in range(n + 1)]
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            byb[b].append(a)
        top1 = [0] * (n + 1)
        top2 = [0] * (n + 1)
        t1 = t2 = 0
        for r in range(1, n + 1):
            for a in byb[r]:
                if a > t1:
                    t2 = t1; t1 = a
                elif a > t2:
                    t2 = a
            top1[r] = t1
            top2[r] = t2
        base = sum(r - top1[r] for r in range(1, n + 1))
        D = [0] * (n + 1)
        for r in range(1, n + 1):
            D[r] = D[r - 1] + (top1[r] - top2[r])
        tl = top1[1:]
        best = 0
        for b in range(1, n + 1):
            for a in byb[b]:
                e = bisect.bisect_right(tl, a) + 1
                lo = b
                if e > lo:
                    gain = D[e - 1] - D[lo - 1]
                else:
                    gain = 0
                if gain > best:
                    best = gain
        return base + best

