from functools import lru_cache
sys.setrecursionlimit(10000)
def brute(M, boxes):
    N=len(boxes)
    @lru_cache(None)
    def f(R, unb):
        # R: sorted tuple of room per type (len M); unb: frozenset of unbought indices
        best=None
        for t in range(M):
            opts=[0]
            if R[t]>0:
                nr=list(R); nr[t]-=1
                opts.append(1+f(tuple(sorted(nr,reverse=True)),unb))
            for j in unb:
                V,P=boxes[j]
                nr=list(R); nr[t]+=V-1
                opts.append(1-P+f(tuple(sorted(nr,reverse=True)),unb-{j}))
            v=max(opts)
            if best is None or v<best: best=v
        return best
    return f(tuple([0]*M), frozenset(range(N)))
