def feas(N, ints):
    # ints: list of (l,r,up) with l<r; returns True if feasible
    # variables 1..N; edges v->u weight w means x_u <= x_v + w
    E=[]
    for (l,r,up) in ints:
        E.append((r,l,0)); E.append((l,r,0))  # x_l<=x_r, x_r<=x_l
        for k in range(l+1,r):
            if up: E.append((l,k,-1))  # x_l <= x_k -1
            else: E.append((k,l,-1))   # x_k <= x_l -1
    d={v:0 for v in range(1,N+1)}
    for _ in range(N+1):
        ch=False
        for (v,u,w) in E:
            if d[v]+w<d[u]:
                d[u]=d[v]+w; ch=True
        if not ch: return True
    return False
