import sys

def c2(y):
    if y == 0:
        return 0
    t = (y & -y).bit_length() - 1
    return 0 if ((y >> (t+1)) & 1) == 0 else 1

def solve(A):
    memo = {}
    def F(S, p):
        if not S:
            return 0
        key = (S, p)
        if key in memo:
            return memo[key]
        if max(S) <= 1:
            best = 0
            for x in range(64):
                if x % 2 != p:
                    continue
                best = max(best, sum(c2(x+a) for a in S))
            memo[key] = best
            return best
        odd = [a for a in S if a & 1]
        even = [a for a in S if not a & 1]
        if p == 0:
            T = tuple(sorted(set(a//2 for a in even)))
            const = lambda q: sum(1 for a in odd if a % 4 == (3 - 2*q) % 4)
        else:
            T = tuple(sorted(set((a+1)//2 for a in odd)))
            const = lambda q: sum(1 for a in even if a % 4 == (2 - 2*q) % 4)
        best = max(const(q) + F(T, q) for q in (0, 1))
        memo[key] = best
        return best
    return max(F(tuple(A), 0), F(tuple(A), 1))

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    A = sorted(set(int(x) for x in data[1:1+n]))
    print(solve(A))

main()

