            c=random.randrange(1,n); f=lambda v:(v*v+c)%n
            x=y=random.randrange(2,n); d=1
            while d==1:
                x=f(x); y=f(f(y)); d=gcd(abs(x-y),n)
            if d!=n: return d
    def fac(n,out):
