from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n=len(grid); m=len(grid[0])
        D=[(-1,1),(1,1),(1,-1),(-1,-1)]
        nxt={1:2,2:0,0:2}
        back=[]; g=[]
        for k,(dr,dc) in enumerate(D):
            B=[[0]*m for _ in range(n)]
            rows=range(n) if dr==1 else range(n-1,-1,-1)
            cols=range(m) if dc==1 else range(m-1,-1,-1)
            for i in rows:
                Bi=B[i]; pi=i-dr
                for j in cols:
                    v=grid[i][j]
                    if v==1:
                        Bi[j]=1
                    else:
                        pj=j-dc
                        if 0<=pi<n and 0<=pj<m and B[pi][pj] and nxt[grid[pi][pj]]==v:
                            Bi[j]=B[pi][pj]+1
            back.append(B)
            G=[[1]*m for _ in range(n)]
            rows=range(n-1,-1,-1) if dr==1 else range(n)
            cols=range(m-1,-1,-1) if dc==1 else range(m)
            for i in rows:
                ni=i+dr
                for j in cols:
                    nj=j+dc
                    if 0<=ni<n and 0<=nj<m and grid[ni][nj]==nxt[grid[i][j]]:
                        G[i][j]=1+G[ni][nj]
            g.append(G)
        ans=0
        for i in range(n):
            for j in range(m):
                for k in range(4):
                    b=back[k][i][j]
                    if b:
                        if b>ans: ans=b
                        t=b+g[(k+1)%4][i][j]-1
                        if t>ans: ans=t
        return ans

