from functools import lru_cache
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        @lru_cache(maxsize=None)
        def F(a, b, last):
            # a odds, b evens remain; last parity: 0 even, 1 odd, 2 none
            if a == 0 and b == 0:
                return 1
            t = 0
            if a and last != 1:
                t += a * F(a - 1, b, 1)
            if b and last != 0:
                t += b * F(a, b - 1, 0)
            return t

        odds = (n + 1) // 2
        evens = n // 2
        total = F(odds, evens, 2)
        if k > total:
            return []
        res = []
        remaining = list(range(1, n + 1))
        last = 2
        a, b = odds, evens
        for _ in range(n):
            for v in remaining:
                p = v & 1
                if last == p:
                    continue
                if p == 1:
                    c = F(a - 1, b, 1)
                else:
                    c = F(a, b - 1, 0)
                if k > c:
                    k -= c
                    continue
                res.append(v)
                remaining.remove(v)
                if p == 1:
                    a -= 1
                else:
                    b -= 1
                last = p
                break
        return res

