class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        pw = [0] * n
        p = 1 % k
        for e in range(n):
            pw[e] = p
            p = p * 10 % k
        w = [0] * h
        for i in range(h):
            j = n - 1 - i
            w[i] = pw[i] if i == j else (pw[i] + pw[j]) % k
        reach = [None] * (h + 1)
        base = [False] * k
        base[0] = True
        reach[h] = base
        for i in range(h - 1, -1, -1):
            nxt = reach[i + 1]
            new = [False] * k
            for d in range(10):
                c = d * w[i] % k
                for s in range(k):
                    if nxt[s]:
                        new[(s + c) % k] = True
            reach[i] = new
        if not reach[0][0]:
            return "-1"
        r = 0
        half = []
        for i in range(h):
            found = False
            for d in range(9, -1, -1):
                if i == 0 and d == 0:
                    continue
                nr = (r + d * w[i]) % k
                if reach[i + 1][(-nr) % k]:
                    half.append(d)
                    r = nr
                    found = True
                    break
            if not found:
                return "-1"
        s = ''.join(map(str, half))
        return s + s[:n // 2][::-1]

