from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        a = nums
        ng = [n] * n
        st = []
        for i in range(n - 1, -1, -1):
            while st and a[st[-1]] <= a[i]:
                st.pop()
            ng[i] = st[-1] if st else n
            st.append(i)
        W = [0] * (n + 1)
        for c in range(n - 1, -1, -1):
            W[c] = W[ng[c]] + a[c] * (ng[c] - c)
        LOG = max(1, n.bit_length())
        up = [ng + [n]]
        for j in range(1, LOG):
            prev = up[-1]
            up.append([prev[prev[c]] for c in range(n + 1)])
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + a[i]

        def cost(l, r):
            c = l
            for j in range(LOG - 1, -1, -1):
                nc = up[j][c]
                if nc <= r:
                    c = nc
            return W[l] - W[c] + a[c] * (r + 1 - c) - (P[r + 1] - P[l])

        ans = 0
        l = 0
        for r in range(n):
            while cost(l, r) > k:
                l += 1
            ans += r - l + 1
        return ans

