import sys

def solve(n, a):
    order = sorted(range(n), key=lambda i: a[i])
    rank = [0] * n
    for r, i in enumerate(order):
        rank[i] = r + 1
    LOG = 1
    while (1 << LOG) <= n:
        LOG += 1

    def add(cnt, sm, i):
        p = rank[i]; v = a[i]
        while p <= n:
            cnt[p] += 1; sm[p] += v; p += p & -p

    def low(cnt, sm, m):
        pos = 0; rem = m; s = 0
        for b in range(LOG, -1, -1):
            np_ = pos + (1 << b)
            if np_ <= n and cnt[np_] <= rem:
                pos = np_; rem -= cnt[np_]; s += sm[np_]
        return s

    def prefix_f(seq_idx):
        cnt = [0] * (n + 1); sm = [0] * (n + 1)
        total = 0; res = {0: 0}; k = 0
        for i in seq_idx:
            add(cnt, sm, i); total += a[i]; k += 1
            if k % 2 == 0:
                res[k] = total - 2 * low(cnt, sm, k // 2)
        return res

    if n % 2 == 0:
        return prefix_f(range(n))[n]
    pre = prefix_f(range(n))
    suf = prefix_f(range(n - 1, -1, -1))
    best = -1
    for s in range(0, n, 2):
        best = max(best, pre[s] + suf[n - 1 - s])
    return best

