def kmp_all(t, x):
    n, m = len(t), len(x)
    if m == 0:
        return list(range(n + 1))
    f = [0] * m
    k = 0
    for i in range(1, m):
        while k and x[i] != x[k]:
            k = f[k - 1]
        if x[i] == x[k]:
            k += 1
        f[i] = k
    res = []
    k = 0
    for i, ch in enumerate(t):
        while k and ch != x[k]:
            k = f[k - 1]
        if ch == x[k]:
            k += 1
        if k == m:
            res.append(i - m + 1)
            k = f[k - 1]
    return res

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        A, B, C = p[:i1], p[i1+1:i2], p[i2+1:]
        oA = kmp_all(s, A); oB = kmp_all(s, B); oC = kmp_all(s, C)
        if not oA or not oB or not oC:
            return -1
        best = -1
        la, lb, lc = len(A), len(B), len(C)
        for k in oB:
            ia = bisect.bisect_right(oA, k - la) - 1
            if ia < 0:
                continue
            ic = bisect.bisect_left(oC, k + lb)
            if ic >= len(oC):
                continue
            L = oC[ic] + lc - oA[ia]
            if best < 0 or L < best:
                best = L
        return best

