import sys
def main():
    data=sys.stdin.buffer.read().split()
    n=int(data[0]); m=int(data[1])
    parent=list(range(n+1)); w=[0]*(n+1)
    def find(x):
        path=[]
        while parent[x]!=x:
            path.append(x); x=parent[x]
        root=x
        acc=0
        for node in reversed(path):
            acc^=w[node]; w[node]=acc; parent[node]=root
        return root
    idx=2
    for _ in range(m):
        x=int(data[idx]); y=int(data[idx+1]); z=int(data[idx+2]); idx+=3
        rx=find(x); px=w[x] if x!=rx else 0
        ry=find(y); py=w[y] if y!=ry else 0
        if rx==ry:
            if px^py!=z:
                print(-1); return
        else:
            parent[rx]=ry
            w[rx]=px^py^z
    groups={}
    pot=[0]*(n+1)
    root=[0]*(n+1)
    for v in range(1,n+1):
        r=find(v)
        root[v]=r
        pot[v]=w[v] if v!=r else 0
        groups.setdefault(r,[]).append(v)
    A=[0]*(n+1)
    for r,nodes in groups.items():
        vals=[pot[v] for v in nodes]
        k=len(nodes)
        c=0
        for b in range(31):
            ones=0
            for t in vals:
                ones+=(t>>b)&1
            if 2*ones>k:
                c|=1<<b
        for v in nodes:
            A[v]=pot[v]^c
    sys.stdout.write(" ".join(map(str,A[1:]))+"\n")
main()

