import sys
from itertools import combinations
from functools import reduce
from operator import xor

def solve(N,K,A):
    total=reduce(xor,A,0)
    if K>N-K:
        m=N-K; flip=True
    else:
        m=K; flip=False
    if m==0:
        S={0}
    elif m==1:
        S=set(A)
    else:
        S={reduce(xor,c) for c in combinations(A,m)}
    if flip:
        return max(s^total for s in S)
    return max(S)

