import random
from collections import deque
def brute(n,edges,S,T):
    adj=[[] for _ in range(n+1)]
    for u,v in edges: adj[u].append(v); adj[v].append(u)
    dist={(S,T):0}; q=deque([(S,T)])
    while q:
        a,b=q.popleft()
        if (a,b)==(T,S): return dist[(a,b)]
        d=dist[(a,b)]
        for x in adj[a]:
            if x!=b and (x,b) not in dist: dist[(x,b)]=d+1; q.append((x,b))
        for y in adj[b]:
            if y!=a and (a,y) not in dist: dist[(a,y)]=d+1; q.append((a,y))
    return -1
def dist_all(n,adj,s):
    d=[-1]*(n+1); d[s]=0; q=deque([s])
    while q:
        x=q.popleft()
        for y in adj[x]:
            if d[y]<0: d[y]=d[x]+1; q.append(y)
    return d
