def solve(N):
    S = math.isqrt(N)
    if S < 2:
        S = 1
    sieve = bytearray([1])*(S+1)
    sieve[0:2] = b'\x00\x00'[:min(2,S+1)]
    for i in range(2, math.isqrt(S)+1):
        if sieve[i]:
            sieve[i*i::i] = bytearray(len(range(i*i, S+1, i)))
    pi = [0]*(S+1)
    c = 0
    for i in range(S+1):
        if sieve[i]:
            c += 1
        pi[i] = c
    primes = [i for i in range(2, S+1) if sieve[i]]
    ordered = 0
    diag = 0
    for p in primes:
        ordered += pi[S//p]
        if p*p <= S:
            diag += 1
    ans = (ordered - diag)//2
    for p in primes:
        if p**8 <= N:
            ans += 1
        else:
            break
    return ans

