import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N = 10000
        sieve = [True] * N
        sieve[0] = sieve[1] = False
        for i in range(2, int(N ** 0.5) + 1):
            if sieve[i]:
                for j in range(i * i, N, i):
                    sieve[j] = False
        if sieve[n] or sieve[m]:
            return -1
        if n == m:
            return n
        L = len(str(n))
        def nbrs(x):
            s = str(x).zfill(L)
            res = []
            for i in range(L):
                d = ord(s[i]) - 48
                for nd in (d - 1, d + 1):
                    if 0 <= nd <= 9:
                        t = s[:i] + chr(48 + nd) + s[i + 1:]
                        res.append(int(t))
            return res
        INF = float('inf')
        dist = {n: n}
        pq = [(n, n)]
        while pq:
