            if runs and runs[-1][0] == ch:
                runs[-1][1] += 1
            else:
                runs.append([ch, 1])
        total = s.count('1')
        best = 0
        for i in range(1, len(runs) - 1):
            if runs[i][0] == '1':
                gain = runs[i - 1][1] + runs[i + 1][1]
                if gain > best:
                    best = gain
        return total + best

