from typing import List
import itertools

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = set(map(tuple, points))
        best = -1
        for (x1, y1), (x2, y2) in itertools.combinations(list(pts), 2):
            if x1 == x2 or y1 == y2:
                continue
            xa, xb = min(x1, x2), max(x1, x2)
            ya, yb = min(y1, y2), max(y1, y2)
            if (xa, ya) not in pts or (xa, yb) not in pts or (xb, ya) not in pts or (xb, yb) not in pts:
                continue
            corners = ((xa, ya), (xa, yb), (xb, ya), (xb, yb))
            ok = True
            for (px, py) in pts:
                if xa <= px <= xb and ya <= py <= yb and (px, py) not in corners:
                    ok = False
                    break
            if ok:
                best = max(best, (xb - xa) * (yb - ya))
        return best

